// Provider-agnostic event layer. Attach a production analytics provider to `window.aarthaAnalyticsProvider.track` when ready.
const analytics = {
  track(event, properties = {}) {
    const payload = { event, properties, timestamp: new Date().toISOString() };
    window.dispatchEvent(new CustomEvent('aartha:analytics', { detail: payload }));
    if (Array.isArray(window.dataLayer)) window.dataLayer.push(payload);
    if (window.aarthaAnalyticsProvider && typeof window.aarthaAnalyticsProvider.track === 'function') window.aarthaAnalyticsProvider.track(event, properties);
  }
};
