function framework() {
  const stages = [['01','Understand','Research the business, market, customer and competition.'],['02','Strategize','Identify opportunities and define the growth plan.'],['03','Execute','Implement the appropriate solutions.'],['04','Measure','Track meaningful KPIs.'],['05','Optimize','Improve based on evidence.'],['06','Grow','Create sustainable business growth.']];
  return `<div class="framework" role="list">${stages.map(([num,title,copy],i)=>`<button class="framework-stage ${i===0?'is-active':''}" type="button" data-stage="${i}" role="listitem"><span class="stage-number">${num}</span><h3>${title}</h3><p>${copy}</p></button>`).join('')}</div>`;
}

function audienceCards() { const data = [['01','Startups','Build visibility and acquire early customers.'],['02','SMEs','Create sustainable digital growth.'],['03','Established Businesses','Optimize marketing and decision-making.'],['04','Organizations','Use research, analytics and strategy.'],['05','Global Clients','Access digital, research and analytics capability remotely.']]; return data.map(([n,t,p])=>`<article class="audience-card"><span class="audience-no">${n}</span><h3>${t}</h3><p>${p}</p></article>`).join(''); }

