function calculator() { return `<section class="section"><div class="container"><div class="section-heading"><p class="eyebrow">Illustrative planning tool</p><h2>What Could Your Marketing Investment Look Like?</h2><p>Adjust the inputs to explore a simple scenario. Estimates are illustrative and do not guarantee future performance.</p></div><div class="calculator"><div class="calc-fields" id="calculator-fields"><div class="field"><label for="budget">Monthly advertising budget <span>NPR</span></label><input id="budget" type="number" min="0" value="50000"></div><div class="field"><label for="value">Average customer value <span>NPR</span></label><input id="value" type="number" min="1" value="12000"></div><div class="field"><label for="cpl">Estimated cost per lead <span>NPR</span></label><input id="cpl" type="number" min="1" value="800"></div><div class="field"><label for="rate">Estimated conversion rate <span>%</span></label><input id="rate" type="number" min="0" max="100" value="12"></div></div><div class="calc-results"><h3>Scenario estimate</h3><div class="result-metrics"><div class="result-metric"><span>Estimated leads</span><strong id="est-leads">63</strong></div><div class="result-metric"><span>Estimated customers</span><strong id="est-customers">8</strong></div><div class="result-metric"><span>Estimated revenue</span><strong id="est-revenue">NPR 96K</strong></div><div class="result-metric"><span>Estimated ROAS</span><strong id="est-roas">1.92×</strong></div></div><div class="mini-bars" aria-hidden="true"><i style="height:32%"></i><i style="height:48%"></i><i style="height:43%"></i><i style="height:68%"></i><i style="height:78%"></i><i style="height:92%"></i></div><p class="disclaimer">Break-even point: <strong id="break-even">5 customers</strong>. Illustrative scenario only; actual outcomes depend on many factors.</p></div></div></div></section>`; }

function contactPage() { return `<main id="main-content">${pageHero('Start a conversation',"Let's Talk About Growth.","Not sure what service you need? That's okay. Tell us the problem you're trying to solve.")}<section class="section section--light"><div class="container contact-grid"><aside class="contact-note"><p class="eyebrow">Start with the question</p><h1>A useful conversation is the first step.</h1><p>We will listen to the problem, ask a few practical questions and help you decide on the next useful action.</p><p class="disclaimer">Please do not include confidential business information in this initial form.</p></aside><form class="contact-form" id="contact-form" novalidate><div class="form-success" role="status">Thanks — your message is ready to be sent. Connect this form to your approved email or CRM service before publishing.</div><div class="form-grid"><div class="field"><label for="name">Name</label><input id="name" name="name" required><div class="form-error"></div></div><div class="field"><label for="organization">Organization</label><input id="organization" name="organization" required><div class="form-error"></div></div><div class="field"><label for="email">Email</label><input id="email" name="email" type="email" required><div class="form-error"></div></div><div class="field"><label for="phone">Phone <span>Optional</span></label><input id="phone" name="phone" type="tel"><div class="form-error"></div></div><div class="field"><label for="business">Business type</label><select id="business" name="business" required><option value="">Select one</option><option>Startup</option><option>Small Business</option><option>Medium Business</option><option>Established Business</option><option>Organization</option></select><div class="form-error"></div></div><div class="field"><label for="challenge">Biggest challenge</label><select id="challenge" name="challenge" required><option value="">Select one</option><option>Customer Acquisition</option><option>Brand Awareness</option><option>Analytics</option><option>Market Expansion</option><option>Operations</option><option>Other</option></select><div class="form-error"></div></div><div class="field field--full"><label for="goal">What would you like to achieve?</label><input id="goal" name="goal" required maxlength="160"><div class="form-error"></div></div><div class="field field--full"><label for="message">Tell us a little more <span>Optional</span></label><textarea id="message" name="message" maxlength="1000"></textarea><div class="form-error"></div></div></div><button class="btn btn--orange" type="submit">Start a Conversation ${icon('arrow')}</button></form></div></section></main>`; }

function render(path) {
  const cleaned = path.replace(/\/$/, '') || '/';
  const route = routes[cleaned] || (cleaned.startsWith('/services/') ? { title: `${serviceData[cleaned.split('/').pop()]?.eyebrow || 'Service'} | Aartha Analytics`, description: 'Aartha capability overview.' } : routes['/']);
  document.title = route.title;
  const meta = document.querySelector('meta[name="description"]'); if (meta) meta.content = route.description;
  let page;
  if (cleaned === '/') page = homePage();
  else if (cleaned === '/how-we-work') page = howWeWork();
  else if (cleaned === '/who-we-help') page = whoWeHelp();
  else if (cleaned === '/work') page = workPage();
  else if (cleaned === '/insights') page = insightsPage();
  else if (cleaned === '/research') page = researchPage();
  else if (cleaned === '/about') page = aboutPage();
  else if (cleaned === '/services') page = servicesPage();
  else if (cleaned === '/growth-diagnostic') page = diagnosticPage();
  else if (cleaned === '/contact') page = contactPage();
  else if (cleaned.startsWith('/services/') && serviceData[cleaned.split('/').pop()]) page = servicePage(serviceData[cleaned.split('/').pop()]);
  else page = homePage();
  const canonical = document.querySelector('link[rel="canonical"]'); if (canonical) canonical.href = `https://aarthaanalytics.com${cleaned}`;
  app.innerHTML = header(cleaned) + page + (cleaned === '/' ? calculator() : '') + footer();
  if (cleaned.startsWith('/services/')) analytics.track('service_viewed', { service: cleaned.split('/').pop() });
  if (cleaned === '/research') analytics.track('research_viewed');
  bindInteractions();
  window.scrollTo({ top: 0, behavior: 'auto' });
}

const diagnosticState = { step: 0, answers: {} };
const questions = [
  { key:'business', label:'Step 1 of 5', question:'What best describes your business?', choices:['Startup','Small Business','Medium Business','Established Business','Organization'] },
  { key:'challenge', label:'Step 2 of 5', question:'What is your biggest challenge right now?', choices:['Customer Acquisition','Brand Awareness','SEO','Social Media','Advertising','Analytics','Market Expansion','Competition','Operations','Other'] },
  { key:'goal', label:'Step 3 of 5', question:'What is the primary goal?', choices:['More Leads','More Sales','Better Visibility','Better Decisions','Market Expansion','Cost Efficiency','Brand Growth'] },
  { key:'assets', label:'Step 4 of 5', question:'Which digital assets do you already use?', multi:true, choices:['Website','Facebook','Instagram','TikTok','SEO','Google Business','Advertising','Analytics'] },
  { key:'measurement', label:'Step 5 of 5', question:'How would you describe your measurement maturity?', choices:["We don't measure much",'Basic metrics','Some analytics','Advanced dashboards'] }
];
function drawDiagnostic() {
  const el = document.getElementById('diagnostic'); if (!el) return;
  if (diagnosticState.step === 5) { el.innerHTML = diagnosticResult(); return; }
  const q = questions[diagnosticState.step]; const value = diagnosticState.answers[q.key] || (q.multi ? [] : '');
  el.innerHTML = `<div class="progress-row"><div class="progress-track" aria-label="Progress">${questions.map((_,i)=>`<i class="progress-dot ${i <= diagnosticState.step?'active':''}"></i>`).join('')}</div><span>${q.label}</span></div><span class="question-label">GROWTH CONTEXT</span><h3>${q.question}</h3><div class="choice-grid" role="group" aria-label="${q.question}">${q.choices.map(x=>`<button type="button" class="choice ${(q.multi ? value.includes(x) : value === x) ? 'selected' : ''}" data-choice="${x}">${q.multi && value.includes(x) ? '✓ ' : ''}${x}</button>`).join('')}</div><div class="diagnostic-actions">${diagnosticState.step ? '<button type="button" class="btn btn--ghost" id="diagnostic-back">Back</button>' : '<span></span>'}<button type="button" class="btn btn--orange" id="diagnostic-next" ${(!q.multi && !value) || (q.multi && !value.length) ? 'disabled' : ''}>${diagnosticState.step === 4 ? 'See my opportunity' : 'Continue'} ${icon('arrow')}</button></div>`;
  el.querySelectorAll('[data-choice]').forEach(btn => btn.addEventListener('click', () => { const choice=btn.dataset.choice; if (diagnosticState.step === 0 && !diagnosticState.answers.business) analytics.track('growth_diagnostic_started'); if(q.multi){ const old=diagnosticState.answers[q.key]||[]; diagnosticState.answers[q.key]=old.includes(choice)?old.filter(x=>x!==choice):[...old,choice]; } else diagnosticState.answers[q.key]=choice; drawDiagnostic(); }));
  const back=el.querySelector('#diagnostic-back'); if(back) back.addEventListener('click',()=>{ diagnosticState.step--; drawDiagnostic(); });
  el.querySelector('#diagnostic-next').addEventListener('click',()=>{ if (diagnosticState.step === 4) analytics.track('growth_diagnostic_completed'); diagnosticState.step++; drawDiagnostic(); });
}
function diagnosticResult() {
  const scores = { 'Digital Growth':0, 'Marketing & Advertising':0, 'Data & Analytics':0, 'Business Development':0, 'Business Support':0 };
  const a=diagnosticState.answers; const add=(key,n)=>scores[key]+=n;
  const challenge={ 'Customer Acquisition':['Digital Growth','Marketing & Advertising','Data & Analytics'], 'Brand Awareness':['Digital Growth','Marketing & Advertising'], 'SEO':['Digital Growth','Data & Analytics'], 'Social Media':['Digital Growth','Marketing & Advertising'], 'Advertising':['Marketing & Advertising','Data & Analytics'], 'Analytics':['Data & Analytics','Business Development'], 'Market Expansion':['Business Development','Digital Growth'], 'Competition':['Business Development','Data & Analytics'], 'Operations':['Business Support','Data & Analytics'], 'Other':['Business Development','Digital Growth'] };
  (challenge[a.challenge]||[]).forEach((x,i)=>add(x,3-i));
  ({'More Leads':['Digital Growth','Marketing & Advertising'], 'More Sales':['Marketing & Advertising','Data & Analytics'], 'Better Visibility':['Digital Growth'], 'Better Decisions':['Data & Analytics','Business Development'], 'Market Expansion':['Business Development'], 'Cost Efficiency':['Data & Analytics','Business Support'], 'Brand Growth':['Digital Growth','Marketing & Advertising']}[a.goal]||[]).forEach((x,i)=>add(x,2-i));
  if ((a.assets||[]).includes('Analytics')) add('Data & Analytics',2); if ((a.assets||[]).includes('SEO')) add('Digital Growth',1); if (a.measurement === "We don't measure much" || a.measurement === 'Basic metrics') add('Data & Analytics',2);
  const sorted=Object.entries(scores).sort((x,y)=>y[1]-x[1]); const primary=sorted[0][0], secondary=sorted[1][0]; const copy={ 'Digital Growth':'Your responses suggest that improving digital visibility and customer acquisition may be your strongest starting point.', 'Marketing & Advertising':'Your responses suggest a focused campaign and performance pathway may be the most useful next step.', 'Data & Analytics':'Your responses suggest that clearer measurement and decision-ready data may unlock the next opportunity.', 'Business Development':'Your responses suggest that market, customer or growth strategy clarity may be the most useful starting point.', 'Business Support':'Your responses suggest that stronger reporting and operational structure may support better growth.' }[primary];
  return `<div class="diagnostic-result"><span class="result-chip">YOUR GROWTH OPPORTUNITY</span><h3>Primary opportunity: ${primary}</h3><p>${copy}</p><p><strong>Secondary opportunity:</strong> ${secondary}</p><div class="path-result">${recommendations(primary).map(x=>`<span>${x}</span>`).join('')}</div>${buttonLink('Discuss Your Growth Opportunity','/contact')}<p class="disclaimer">This is an initial directional assessment, not a formal business diagnosis.</p><button type="button" class="text-link" id="restart-diagnostic">Start again ${icon('arrow')}</button></div>`;
}
function recommendations(primary) { return ({'Digital Growth':['Digital Marketing','SEO','Marketing Analytics'], 'Marketing & Advertising':['Campaign Strategy','Performance Marketing','Marketing Analytics'], 'Data & Analytics':['Business Analytics','Data Visualization','Performance Measurement'], 'Business Development':['Market Research','Competitor Analysis','Growth Strategy'], 'Business Support':['Reporting','Process Improvement','Business Analytics']})[primary]; }

function updateDashboard(tab = 'Marketing') {
  const sets={Marketing:{k:[['Marketing spend','NPR 48K','+12.4%'],['Leads','186','+18.7%'],['Conversion','6.8%','+0.9 pp'],['ROI','2.4×','+0.3×']],channels:[['Search',78],['Social',62],['Referral',46],['Direct',32]],path:'M0,138 L55,121 L110,128 L165,88 L220,101 L275,57 L330,75 L385,29 L440,42',title:'Monthly revenue trend'},Sales:{k:[['Sales pipeline','NPR 428K','+9.8%'],['Opportunities','56','+14.2%'],['Win rate','22.1%','+1.6 pp'],['Sales cycle','18d','−3 days']],channels:[['Qualified',76],['Proposal',55],['Negotiation',39],['Closed',28]],path:'M0,141 L55,132 L110,110 L165,113 L220,75 L275,80 L330,55 L385,65 L440,28',title:'Sales pipeline trend'},Customers:{k:[['New customers','29','+21.0%'],['Retention','84%','+3.1 pp'],['CAC','NPR 2.1K','−8.4%'],['Value','NPR 14K','+5.3%']],channels:[['Returning',81],['New',69],['Referral',51],['Partner',34]],path:'M0,143 L55,118 L110,125 L165,95 L220,103 L275,86 L330,59 L385,47 L440,33',title:'Customer growth trend'},Finance:{k:[['Revenue','NPR 1.24M','+16.8%'],['Gross margin','38%','+2.6 pp'],['Spend','NPR 498K','+4.0%'],['ROAS','2.5×','+0.3×']],channels:[['Core',85],['Growth',65],['Other',42],['New',26]],path:'M0,140 L55,136 L110,117 L165,101 L220,108 L275,68 L330,73 L385,40 L440,31',title:'Revenue trend'}};
  const data=sets[tab]; const k=document.getElementById('kpi-grid'), c=document.getElementById('channel-list'); if(!k || !data) return; k.innerHTML=data.k.map(([x,y,z])=>`<div class="kpi"><small>${x}</small><strong>${y}</strong><span>${z}</span></div>`).join(''); c.innerHTML=data.channels.map(([x,y])=>`<div class="channel"><span>${x}</span><div class="bar"><i style="width:${y}%"></i></div><b>${y}%</b></div>`).join(''); document.getElementById('line-path').setAttribute('d',data.path); document.getElementById('area-path').setAttribute('d',data.path+' L440,164 L0,164Z'); document.getElementById('chart-title').textContent=data.title;
}

function setupCalculator() { const fields=document.getElementById('calculator-fields'); if(!fields) return; const currency=new Intl.NumberFormat('en-US',{maximumFractionDigits:0}); const update=()=>{ const budget=Math.max(0,+document.getElementById('budget').value||0), value=Math.max(1,+document.getElementById('value').value||1), cpl=Math.max(1,+document.getElementById('cpl').value||1), rate=Math.min(100,Math.max(0,+document.getElementById('rate').value||0))/100; const leads=budget/cpl, customers=leads*rate, revenue=customers*value, roas=budget?revenue/budget:0, breakEven=Math.ceil(budget/value); document.getElementById('est-leads').textContent=currency.format(Math.round(leads)); document.getElementById('est-customers').textContent=currency.format(Math.round(customers)); document.getElementById('est-revenue').textContent=`NPR ${currency.format(Math.round(revenue/1000))}K`; document.getElementById('est-roas').textContent=`${roas.toFixed(2)}×`; document.getElementById('break-even').textContent=`${currency.format(breakEven)} customer${breakEven===1?'':'s'}`; }; fields.addEventListener('input',()=>{ if(!calculatorTracked){ analytics.track('calculator_used'); calculatorTracked=true; } update(); }); update(); }

function setupContactForm() { const form=document.getElementById('contact-form'); if(!form) return; let started=false; form.addEventListener('focusin',()=>{if(!started){analytics.track('consultation_started');started=true;}},{once:true}); form.addEventListener('submit', e=>{e.preventDefault(); let valid=true; form.querySelectorAll('[required]').forEach(field=>{const err=field.parentElement.querySelector('.form-error'); let message=''; if(!field.value.trim()) message='This field is required.'; else if(field.type==='email' && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(field.value)) message='Enter a valid email address.'; err.textContent=message; field.setAttribute('aria-invalid',message?'true':'false'); if(message) valid=false;}); if(valid) { analytics.track('consultation_submitted'); form.querySelector('.form-success').classList.add('show'); form.querySelector('.form-success').focus?.(); } }); }

function bindInteractions() {
  document.querySelectorAll('.btn').forEach(btn=>btn.addEventListener('click',()=>analytics.track('cta_clicked', { label: btn.textContent.trim().replace(/\s+/g,' ') })));
  const toggle=document.querySelector('.menu-toggle'), menu=document.querySelector('.nav-links'); if(toggle && menu){toggle.addEventListener('click',()=>{const open=menu.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.textContent=open?'×':'☰';}); menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>menu.classList.remove('open')));}
  document.querySelectorAll('.pathway-option').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.pathway-option').forEach(x=>x.classList.remove('is-active'));btn.classList.add('is-active'); const maps={'More Customers':'Digital Growth + Analytics + Strategy','Better Visibility':'SEO + Content + Digital Presence','Better Marketing ROI':'Performance Marketing + Analytics','Better Business Decisions':'Analytics + Data Visualization + Strategy','Market Expansion':'Market Research + Strategy + Digital Growth','Better Data':'Business Analytics + Dashboard Design'};document.getElementById('pathway-result').textContent=maps[btn.dataset.pathway];}));
  document.querySelectorAll('.framework-stage').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.framework-stage').forEach(x=>x.classList.remove('is-active'));btn.classList.add('is-active');}));
  drawDiagnostic(); const restart=document.getElementById('restart-diagnostic'); if(restart) restart.addEventListener('click',()=>{diagnosticState.step=0;diagnosticState.answers={};drawDiagnostic();});
  document.querySelectorAll('.dash-tab').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.dash-tab').forEach(x=>{x.classList.remove('active');x.setAttribute('aria-selected','false')});btn.classList.add('active');btn.setAttribute('aria-selected','true');updateDashboard(btn.dataset.dash);})); updateDashboard(); setupCalculator(); setupContactForm();
}

window.addEventListener('hashchange',()=>render(location.hash.slice(1)||'/'));
render(location.hash.slice(1)||'/');
